</code></pre> <pre><code>//- Во-первых, словим дедлок, так как будем читать из канала, который никто не закроет
//- Во-вторых, между чтением из мапы и записью в мапу - будут втискиваться горутины до закрыти мьютекса и будем ловить read write и получать дубли

package main

import (
    "fmt"
    "math/rand"
    "sync"
)

func main() {
    alreadyStored := make(map[int]struct{})
    mu := sync.Mutex{}
    capacity := 1600

    doubles := make([]int, 0, capacity)
    for i := 0; i &lt; capacity; i++ {
        doubles = append(doubles, rand.Intn(10)) // create rand num 0...9
    }
    // 3, 4, 5, 0, 4, 9, 8, 6, 6, 5, 5, 4, 4, 4, 2, 1, 2, 3, 1

    uniqueIDs := make(chan int, capacity)
    wg := sync.WaitGroup{}

    for i := 0; i &lt; capacity; i++ {
        i := i
        wg.Add(1)
        go func() {
            defer wg.Done()
            mu.Lock()
            defer mu.Unlock()
            if _, ok := alreadyStored[doubles[i]]; !ok {
                alreadyStored[doubles[i]] = struct{}{}
                uniqueIDs &lt;- doubles[i]
            }
        }()

    }

    wg.Wait()
    close(uniqueIDs)
    for val := range uniqueIDs {
        fmt.Println(val)
    }

    fmt.Printf("len of ids: #{len (uniqueIDs)H\n") // 0, 1, 2, 3,
    fmt.Println(uniqueIDs)
}
</code></pre> <ul> <li>Во-первых, словим дедлок, так как будем читать из канала, который никто не закроет</li> <li>Во-вторых, между чтением из мапы и записью в мапу - будут втискиваться горутины до закрыти мьютекса и будем ловить read write и получать дубли</li> </ul>

Что произойдет? Условие <pre><code>package  main
