</code></pre> <p>Необходимо заполнить</p> Что произойдет и как починить? УсловиеРешениеОбъяснение <pre><code>package main

import "fmt"

func main() {
    c := make(chan string)

    i := 0
    for ; i &lt; 5; i++ {
        go func() {
            c &lt;- fmt.Sprintf("%d", i)
