        println(&lt;-c)
    }
}
</code></pre> <pre><code>package main

import (
    "fmt"
    "sync"
)

// 5, 5, 5, 5, 5 fatal error: all goroutines are asleep - deadlock!
func Task() {
    c := make(chan string)
    i := 0
    for ; i &lt; 5; i++ {
        go func() {
            c &lt;- fmt.Sprintf("%d", i)
        }()
    }
    for {
        println(&lt;-c)
    }
}

// Solution 1:
func Solution1() {
    c := make(chan string)

    var wg sync.WaitGroup

    for i := 0; i &lt; 5; i++ {
        wg.Add(1)

        i := i

        go func() {
            defer wg.Done()
            c &lt;- fmt.Sprintf("%d", i)
        }()
    }

    go func() {
        wg.Wait()
        close(c)
    }()

    for v := range c {
        fmt.Print(v)
    }
}

// Solution 2:
func Solution2() {
    c := make(chan string)
    done := make(chan struct{})

    for i := 0; i &lt; 5; i++ {
        i := i

        go func() {
            c &lt;- fmt.Sprintf("%d", i)
            done &lt;- struct{}{}
        }()

    }

    go func() {
        for i := 0; i &lt; 5; i++ {
            &lt;-done
        }
        close(c)
    }()

    for {
        select {
        case v, ok := &lt;-c:
            if !ok {
                return
            }
            fmt.Print(v)
        }
    }

}

func run(f func()) {
    f()
}

func main() {
    run(Solution2)
}
</code></pre> <p>Необходимо заполнить</p> Что будет и как изменить? УсловиеРешениеОбъяснение <pre><code>func WaitToCloseManyChans(a, b chan bool) {
    var aclosed, bclosed bool
    for !aclosed || !bclosed {
        select {
        case &lt;-a:
            aclosed = true
        case &lt;-b:
            bclosed = true
        }
    }
}
</code></pre> <pre><code>package main

import (
    "fmt"
    "time"
)

func WaitToCloseManyChans(a, b chan bool) {
    var aclosed, bclosed bool
    for !aclosed || !bclosed {
        select {
        case &lt;-a:
            aclosed = true
        case &lt;-b:
            bclosed = true
        }
    }
}

func WaitToCloseManyChansSol(a, b chan bool) {
    for a != nil || b != nil {
        select {
        case &lt;-a:
            a = nil
        case &lt;-b:
            b = nil
        }
    }
}

func main() {
    a := make(chan bool)
    b := make(chan bool)

    go func() {
        time.Sleep(1 * time.Second)
        a &lt;- true
        close(a)
    }()

    go func() {
        time.Sleep(2 * time.Second)
        b &lt;- true
        close(b)
    }()

    WaitToCloseManyChansSol(a, b)
    fmt.Println("Both channels are closed")
}
</code></pre> <p>Необходимо заполнить</p> Что будет выведено на экран? УсловиеРешениеОбъяснение <pre><code>func main(){
