func merge[T any](chans ...chan T) chan T {
    result := make(chan T, 1024)

    go func() {
        wg := &amp;sync.WaitGroup{}
        wg.Add(len(chans))

        for _, ch := range chans {
            ch := ch
            go func() {
                defer wg.Done()
                for val := range ch {
                    result &lt;- val
                }
            }()
        }

        wg.Wait()
        close(result)
    }()

    return result
