    head.Next = tail
    tail.Prev = head
    return newLRUCache(head, tail, capacity)
}

func (this *LRUCache) Get(key int) int {
    if node, ok := this.Mp[key]; ok {
        this.remove(node)
        this.insert(node)
        return node.Val
    }

    return -1
}

func (this *LRUCache) Put(key int, value int) {
    if node, ok := this.Mp[key]; ok {
        this.remove(node)
    }

    if len(this.Mp) &gt;= this.Capacity {
        this.remove(this.Tail.Prev)
    }

    this.insert(&amp;Node{Key: key, Val: value})
}

func (this *LRUCache) remove(node *Node) {
    delete(this.Mp, node.Key)
    node.Next.Prev = node.Prev
    node.Prev.Next = node.Next
}

func (this *LRUCache) insert(node *Node) {
    this.Mp[node.Key] = node
    next := this.Head.Next
    this.Head.Next = node
    next.Prev = node
    node.Prev = this.Head
    node.Next = next
}

```
</code></pre> Объяснение <p>🏓 Первое решение: написать структуру, в которой будет мапа и мьютекс. Таким образом просто и очень быстро запилить первое рабочее решение. Потом немного подумать и понять, что мьютекс можно замнить на RWMutex, чтобы ускорить чтение.</p> <p>🥊 Описанное выше решение может хорошо подойти джуну+/мидлу-, но мидлы-сеньеры здесь не остановятся. И на следующем вопросе от интервьюера про то, как ускорить чтение, начнут рассуждать.</p> <p>❓На какие вопросы какие темы стоит поднимать: - Как ускорить чтение? И может даже запись? Можно порассуждать про шардирование, подумать, каким алгоритмам решардинга тут можно воспользоваться - углубляться как только можно - А что если хочет сохранять на диск, знаешь уже такие кейсы в других in-memory базах? Да, рассказываешь, чем плоха и хороша персистентность редиса - Какие проблемы могут возникнуть? В случае in-memory key/value известная проблема - это переполнение кэша, поэтому нужно думать о вытеснении. Тут есть смысл рассказать про LRU, LFU, TTL и другие алгоритмы. Один инстанс мапы упадет, что делать - еще одна проблема. Тут есть смысл рассказать про репликацию, копая в самую глубь. А как с шардирование соединяться? - далекий вопрос в сторону дизайна и опыта: Какие юзкейсы применения такого in-memory key/value видишь? На этот вопрос будет в пост в скором времени - совсем далекий: А что если бы ты разворачивал на двух и более дц, как избегать network partitionов, как сделать так, чтобы если один дц упадет - все было все равно доступно?</p> Сделать кастомную реализацию WaitGroup на семафоре ОписаниеРешениеРешение 2 <p>Семафо́р (англ. semaphore) — примитив синхронизации работы процессов и потоков, в основе которого лежит счётчик, над которым можно производить две атомарные операции: увеличение и уменьшение значения на единицу, при этом операция уменьшения для нулевого значения счётчика является блокирующейся.</p> <p>Семафор можно легко получить из канала. Чтоб не аллоцировать лишние данные, будем складывать туда пустые структуры.</p> <pre><code>package main

type Semaphore chan struct{}

func (s Semaphore) Increment(n int) {
    for i := 0; i &lt; n; i++ {
        s &lt;- struct{}{}
    }
}

func (s Semaphore) Decrement(n int) {
    for i := 0; i &lt; n; i++ {
        &lt;-s
    }
}

func main() {
    const count = 5

    var s = make(Semaphore, count)

    for i := 0; i &lt; count; i++ {
        go func(n int) {
