}
</code></pre> <pre><code>package main

import (
"sync"
"sync/atomic"
)

type WaitGroup struct {
state int32 // atomic usage only

subsMu sync.Mutex
subs   []chan struct{}
}

func NewWaitGroup() WaitGroup { return WaitGroup{subs: make([]chan struct{}, 0)} }

func (wg *WaitGroup) Add(n uint) { atomic.AddInt32(&amp;wg.state, int32(n)) }

func (wg *WaitGroup) Done() {
if atomic.AddInt32(&amp;wg.state, -1); atomic.LoadInt32(&amp;wg.state) &lt;= 0 {
    wg.subsMu.Lock()

    if wg.subs != nil {
    for i := 0; i &lt; len(wg.subs); i++ {
        close(wg.subs[i]) // закрытие "стриггерит" все каналы
    }

    wg.subs = nil
    }

    wg.subsMu.Unlock()
}
}

func (wg *WaitGroup) Wait() {
if atomic.LoadInt32(&amp;wg.state) &gt; 0 {
    var c = make(chan struct{})

    wg.subsMu.Lock()
    wg.subs = append(wg.subs, c)
    wg.subsMu.Unlock()

    &lt;-c // ожидаем закрытия канала (блокируемся)
}

return
}

func main() {
var wg = NewWaitGroup()

wg.Wait() // пролетает сразу же, так как не было вызовов Add()

wg.Add(2)
wg.Add(0) // ничего не делает
wg.Done()
wg.Done()
wg.Wait() // тоже пролетает сразу же

for i := 0; i &lt; 5; i++ {
    wg.Add(1)

    go func(n int) {
    defer wg.Done()

    print(n, " ")
    }(i)
}

wg.Wait() // 1 4 3 2 0 (порядок будет произвольный)
}
</code></pre> Мердж каналов ОписаниеРешение <p>Даны n каналов типа chan int. Надо написать функцию, которая смерджит все данные из этих каналов в один и вернет его. Мы хотим, чтобы результат работы функции выглядел примерно так:</p> <p><pre><code>package main

func main() {
    var a, b, c = make(chan int), make(chan int), make(chan int)

    // ...

    for num := range joinChannels(a, b, c) {
        println(num)
    }
}
</code></pre> Для этого создаём канал для смердженных данных, запускаем N горутин для чтения из каналов (по количеству каналов), и используем дополнительный канал для того, чтоб определить когда у нас работа будет завершена (эдакий аналог sync.WaitGroup)</p> <pre><code>package main

func joinChannels(in ...&lt;-chan int) &lt;-chan int {
var (
    out  = make(chan int, len(in))
    done = make(chan struct{}) // канал для пустых сообщений, аналог sync.WaitGroup
)

for i := 0; i &lt; len(in); i++ { // запускаем горутины по кол-ву каналов на входе
    go func(c &lt;-chan int) {
    defer func() { done &lt;- struct{}{} }() // по завершению работы пишем в канал "done"

    for {
        value, isOpened := &lt;-c
        if !isOpened { // если канал закрылся - то выходим
        return
        }

        out &lt;- value // иначе пишем в результирующий канал
    }
    }(in[i])
}

go func() { // запускаем отдельную горутину, которая ожидает завершения работы
    for i := 0; i &lt; len(in); i++ { // с помощью этого счётчика
    &lt;-done // который N раз просто читает пустую структуру и блокируется
    }

    close(done)
    close(out)
}()

return out
}

func main() {
var a, b, c = make(chan int), make(chan int), make(chan int)

go func() {
    for _, num := range []int{1, 2, 3} { a &lt;- num }
    close(a)
}()

go func() {
    for _, num := range []int{20, 10, 30} { b &lt;- num }
    close(b)
}()

go func() {
    for _, num := range []int{300, 200, 100} { c &lt;- num }
    close(c)
}()

for num := range joinChannels(a, b, c) {
    println(num) // 1, 2, 3, 20, 10, 300, 200, 30, 100
}
}
</code></pre>

Что такое heap и stack? <p>Стек (stack) - это область оперативной памяти, которая создаётся для каждого потока. Он работает в порядке LIFO (Last In, First Out), то есть последний добавленный в стек кусок памяти будет первым в очереди на вывод из стека. Каждый раз, когда функция объявляет новую переменную, она добавляется в стек, а когда эта переменная пропадает из области видимости (например, когда функция заканчивается), она автоматически удаляется из стека. Когда стековая переменная освобождается, эта область памяти становится доступной для других стековых переменных.</p> <p>Стек быстрый, так как часто привязан к кэшу процессора. Размер стека ограничен, и задаётся при создании потока.</p> <p>Куча (heap) - это хранилище памяти, также расположенное в ОЗУ, которое допускает динамическое выделение памяти и не работает по принципу стека: это просто склад для ваших переменных. Когда вы выделяете в куче участок памяти для хранения переменной, к ней можно обратиться не только в потоке, но и во всем приложении. Именно так определяются глобальные переменные. По завершении приложения все выделенные участки памяти освобождаются. Размер кучи задаётся при запуске приложения, но, в отличие от стека, он ограничен лишь физически, и это позволяет создавать динамические переменные.</p> <p>В сравнении со стеком, куча работает медленнее, поскольку переменные разбросаны по памяти, а не сидят на верхушке стека. То что попадает в кучу, живёт там пока не придёт GC.</p> <p>Но почему стек так быстр? Основных причин две:</p> <p>Стеку не нужно иметь сборщик мусора (garbage collector). Как мы уже упоминали, переменные просто создаются и затем вытесняются, когда функция завершается. Не нужно запускать сложный процесс освобождения памяти от неиспользуемых переменных и т.п. Стек принадлежит одной горутине, переменные не нужно синхронизировать в сравнении с теми, что находятся в куче. Что также повышает производительность</p> Где выделяется память под переменную? Можно ли этим управлять? <p>Прямых инструментов для управления местом, где будет выделена память у нас, к сожалению - нет. Но есть некоторые практики, которые позволяют это понять и использовать эффективно.</p> <p>Память под переменную может быть выделена в куче (heap) или стеке (stack). Очень приблизительно:</p> <p>Стек содержит последовательность переменных для заданной горутины (как только функция завершила работу, переменные вытесняются из стека) Куча содержит общие (shared) переменные (глобальные и т.п.) Давайте рассмотрим простой пример, в котором вы возвращаем значение: <pre><code>func getFooValue() foo {
    var result foo
    // Do something
    return result
}
</code></pre> Здесь переменная result создаётся в текущей горутине. И эта переменная помещается в стек. Как только функция завершает работу, клиент получает копию этой переменной. Исходная переменная вытесняется из стека. Эта переменная всё ещё существует в памяти, до тех пор, пока не будет затёрта другой переменной, но к этой переменной уже нельзя получить доступ.</p> <p>Теперь тот же пример, но с указателем: <pre><code>func getFooPointer() *foo {
    var result foo
    // Do something
    return &amp;result
}
</code></pre> Переменная result также создаётся текущей горутиной, но клиент получает указатель (копию адреса переменной). Если result вытеснена из стека, клиент функции не сможет получить доступ к переменной.</p> <p>В подобном сценарии компилятор Go вынужден переместить переменную result туда, где она может быть доступна (shared) – в кучу (heap).</p> <p>Хотя есть и исключение. Для примера: <pre><code>func main()  {
    p := &amp;foo{}
    f(p)
}
</code></pre> Поскольку мы вызываем функцию f() в той же горутине, что и функцию main(), переменную p не нужно перемещать. Она просто находится в стеке и вложенная функция f() будет иметь к ней доступ.</p> <p>В качестве заключения, когда мы создаём функцию - поведением по умолчанию должно быть использование передачи по значению, а не по указателю. Указатель должен быть использован только когда мы действительно хотим переиспользовать данные.</p> Как работает Garbage Collection (GC) в Go? <p>Garbage Collection - это процесс освобождения места в памяти, которая больше не используется. Стек освобождается быстро и просто (условно-самостоятельно), а вот с кучей имеются некоторые сложности.</p> <p>В основе работы GC в Go лежит:</p> <p>“Трехцветный алгоритм пометки и очистки” (выполняется параллельно с основной программой) - все данные в куче представляются в виде связанного графа, каждая вершина которого (каждый объект, данные) может быть помечена как “белая”, “серая”, или “чёрная”; данный граф обходится в несколько проходов, все вершины размечаются своими цветами, и “белые” (мусорные) объекты могут быть удалены (“чёрные” - точно нельзя удалять; “серые” - под вопросом, пока не трогать) Write Barrier, следящий за тем, чтоб черные объекты не указывали на белые; и “останавливать мир” (Stop The World, STW) для включения или отключения Write Barrier GC можно вызвать ручками - runtime.GC(), но пользоваться этим нужно с осторожностью (есть риск блокировки вызывающей стороны или всего приложения целиком).</p> <p>По умолчанию, GC запускается самостоятельно когда размер кучи становится в 2 раза больше (за это отвечает Pacer; данный коэффициент можно регулировать при сборке с помощью env GOGC).</p> <p>Полный цикл работы GC:</p> <ol> <li>Sweep termination - фаза завершения очистки:</li> <li>Stop the World</li> <li>Ожидаем пока все горутины достигнут safe-point</li> <li>Завершаем очистку ресурсов</li> <li>Mark phase - фаза разметки (выполняется конкурентно с основной программой, выделяется на неё ~25% CPU):</li> <li>Включаем Write Barrier</li> <li>Start the World</li> <li>Запускаем сканирование глобальных переменных и стеков</li> <li>При сканировании работа горутины приостанавливается (но не происходит полная остановка всей программы)</li> <li>Выполняем 3-х цветный алгоритм поиска мусора</li> <li>Mark termination - фаза завершения разметки</li> <li>Stop the World (не является обязательной, но с ней проце было реализовать)</li> <li>Дожидаемся завершения обработки последних задач из очереди</li> <li>Очистка кэшей</li> <li>Завершаем разметку</li> <li>Sweep phase - фаза очистки</li> <li>Отключаем Write Barrier</li> <li>Start The World</li> <li>Очистка ресурсов происходит в фоне</li> </ol> <p>👎 Недостатки:</p> <ul> <li>Не реализован алгоритм поколений (GC Generations)</li> <li>Не реализовано уплотнение</li> <li>Stop the World (STW), вызываемый аж дважды</li> <li>Нет возможности тонкой настройки</li> </ul> <p>Для оптимизации можно:</p> <ul> <li>Уменьшить частоту вызова GC с помощью GOGC</li> <li>Использовать балласт (выделять большое количество памяти при запуске приложения make([]byte, 10 &lt;&lt; 30) // 10 GiB), который увеличивает базовый размер кучи, не будет выделен как мусор, помечается за O(1), и выделяется в виртуальном пространстве не используя физическую память</li> <li>Использовать sync.Pool (он хорошо дружит с GC)</li> </ul> Какое поведение по умолчанию используется в Go при передаче в функцию? <p>По умолчанию всегда используется копирование, т.е. передача по значению. Для передачи по указателю необходимо это явно указывать: <pre><code>func main() {
    var i = 5

    byValue(i)    // 5
    byPointer(&amp;i) // 5
}

func byValue(i int)    { println(i) }  // передача по значению (копии переменной)
func byPointer(i *int) { println(*i) } // передача по указателю
</code></pre></p> Что можешь рассказать про escape analysis? <p>Escape analysis - это процесс, который компилятор использует для определения размещения значений, созданных вашей программой.</p> <p>В частности, компилятор выполняет статический анализ кода, чтобы определить, может ли значение быть помещено в стековый фрейм для функции, которая его строит, или значение должно “сбежать” в кучу. Используется разработчиками для оптимизации кода и аналитики причин возможного замедления.</p> <p>Команда для запуска escape-анализа: go build -gcflags="-m" (так же можно использовать флаги -N для отключени оптимизаций, -l для отключения “инлайнинга”).</p>

Дополнительный блок фигурных скобок в функции <p>Его можно использовать, и он означает отдельный скоуп для всех переменных, объявленных в нём (возможен и “захват переменных” объявленных вне скоупа ранее, естественно). Иногда используется для декомпозиции какого-то отдельного куска функции, к примеру.</p> <pre><code>var i, s1 = 1, "foo"

{
    var j, s2 = 2, "bar"

    println(i, s1) // 1 foo
    println(j, s2) // 2 bar

    s1 = "baz"
}

println(i, s1) // 1 baz
//println(j, s2) // ERROR: undefined: j and s2
</code></pre> <p>Так же это может быть связано с AST (Abstract Syntax Tree) - когда оно строится и происходят SSA (Static Single Assignment) оптимизации, к сожалению SSA не работает на всю длину дерева. Как следствие, если у нас слишком длинная функция (примерно дохулион строк) и мы по каким-то причинам не можем её декомпозировать, но можем изолировать какие-то скоупы то, таким образом, мы помогаем SSA произвести оптимизации (если они возможно).</p> Что такое замыкание? <p>Замыкания - это такие функции, которые вы можете создавать в рантайме и им будет доступно текущее окружение, в рамках которого они были созданы.</p> <p>Функции, у которых есть имя - это именованные функции. Функции, которые могут быть созданы без указания имени - это анонимные функции.</p> <p><pre><code>func main() {
    var text = "some string"

    var ourFunc = func() { // именованное замыкание
        println(text)
    }

    ourFunc() // some string
    getFunc()() // another string
}

func getFunc() func() {
    return func() { // анонимное
        println("another string")
    }
}
</code></pre> Замыкания сохраняют состояние. Это означает, что состояние переменных содержится в замыкании в момент декларации. Одна из самых очевидных ловушек - это создание замыканий в цикле:</p> <pre><code>var funcs = make([]func(), 0, 5)

for i := 0; i &lt; 5; i++ {
    funcs = append(funcs, func() { println("counter =", i) })

    // исправляется так:
    //var value = i
    //funcs = append(funcs, func() { println("counter =", value) })
}

for _, f := range funcs {
    f()
}

// counter = 5 (так все 5 раз)
</code></pre> Что такое сериализация? Зачем она нужна? <p>Сериализация - это процесс преобразования объекта в поток байтов для сохранения или передачи. Обратной операцией является десериализация (т.е. восстановление объекта/структуры из последовательности байтов). Синонимом можно считать термин “маршалинг” (от англ. marshal - упорядочивать).</p> <p>Из минусов сериализации можно выделить нарушение инкапсуляции, т.е. после сериализации “приватные” свойства структур могут быть доступны для изменения.</p> <p>Типичными примерами сериализации в Go являются преобразование структур в json-объекты. Кроме json существуют различные кодеки типа MessagePack, CBOR и т.д.</p> Что такое type switch? <p>Проверка типа переменной, а не её значения. Может быть в виде одного switch и множеством case:</p> <p><pre><code>package main

func checkType(i interface{}) {
switch i.(type) {
case int:
    println("is integer")

case string:
    println("is string")

default:
    println("has unknown type")
}
}
</code></pre> А может в виде if-конструкции:</p> <pre><code>package main

func main() {
    var any interface{}

    any = "foobar"

    if s, ok := any.(string); ok {
        println("this is a string:", s)
    }

    // а так можно проверить наличие функций у структуры
    if closable, ok := any.(interface{ Close() }); ok {
        closable.Close()
    }
}
</code></pre> Что такое захват переменной? <p>Во вложенном скоупе есть возможность обращаться к переменным, объявленных в скоупе выше (но не наоборот). Обращение к переменным из вышестоящего скоупа и есть их захват. Типичной ошибкой является использование значение итератора в цикле:</p> <pre><code>var out []*int

for i := 0; i &lt; 3; i++ {
    out = append(out, &amp;i)
}

println(*out[0], *out[1], *out[2]) // 3 3 3
Copy
Испраляется путём создания локальной (для скоупа цикла) переменной с копией знаяения итератора:

var out []*int

for i := 0; i &lt; 3; i++ {
    i := i // Copy i into a new variable.
    out = append(out, &amp;i)
}

println(*out[0], *out[1], *out[2]) // 0 1 2
</code></pre> Как работает defer? <p>Defer является функцией отложенного вызова. Выполняется всегда (даже в случае паники внутри функции вызываемой) после того, как функция завершила своё выполнение но до того, как управление вернётся вызывающей стороне (более того - внутри defer возможен захват переменных, и даже возвращаемого результата). Часто используется для освобождения ресурсов/снятия блокировок. Пример использования:</p> <p><pre><code>func main() {
    println("result =", f())
    // f started
    // defer
    // defer in defer
    // result = 25
}

func f() (i int) {
    println("f started")

    defer func() {
        recover()

        defer func() { println("defer in defer"); i += 5 }()

        println("defer")

        i = i * 2
    }()

    i = 10

    panic("panic is here")
}
</code></pre> Когда выполняется ключевое слово defer, оно помещает следующий за ним оператор в список, который будет вызван до возврата функции.</p> Как работает init? <p>В Go есть предопределенная функция init(). Она выделяет фрагмент кода, который должен выполняться перед всеми другими частями пакета. Этот код будет выполняться сразу после импорта пакета.</p> <p>Также функция init() используется для автоматической регистрации одного пакета в другом (например, так работает подавляющее большинство “драйверов” для различных СУБД, например - go-sql-driver/mysql/driver.go).</p> <p>Функцию init() можно использовать неоднократно в рамках даже одного файла, выполняться они будут в этом случае в порядке, как их встречает компилятор.</p> <p>Хотя использование init() и является довольно полезным, но часто оно затрудняет чтение/понимание кода, и (почти) всегда можно обойтись без неё, поэтому необходимость её использования - всегда очень большой вопрос.</p> Прерывание for/switch или for/select <p>Что произойдёт в следующем примере, если f() вернёт true? <pre><code>for {
switch f() {
case true:
    break
case false:
    // Do something
}
}
</code></pre> Очевидно, будет вызван break. Вот только прерван будет switch, а не цикл for. Простое решение проблемы – использовать именованный (labeled) цикл и вызывать break c этой меткой, как в примере ниже:</p> <pre><code>loop:
for {
    switch f() {
    case true:
    break loop
    case false:
    // Do something
    }
}
</code></pre> Сколько можно возвращать значений из функции? <p>Теоретически, неограниченное количество значений. Так же хочется отметить, что есть правила “де-факто”, которых следует придерживаться:</p> <ul> <li>Последним значением возвращать ошибку, если её возврат подразумевается</li> <li>Первым значением возвращать контекст, если он подразумевается</li> <li>Хорошим тоном является не возвращать более четырёх значений</li> <li>Если функция что-то проверяет и возвращает значение + булевый результат проверки - то результат проверки возвращать последним (пример - os.LookupEnv(key string) (string, bool))</li> <li>Если возвращается ошибка, то остальные значения возвращать нулевыми или nil</li> </ul> Дженерики - это про что? <p>Дженерики, или обобщения - это средства языка, позволяющего работать с различными типами данных без изменения их описания.</p> <p>В версии 1.18 появились дженерики (вообще-то они были и ранее, но мы не могли их использовать в своём коде - вспомни функцию make(T type)), и они позволяют объявлять (описывать) универсальные методы, т.е. в качестве параметров и возвращаемых значений указывать не один тип, а их наборы.</p> <p>Появились новые ключевые слова:</p> <p>any - аналог interface{}, можно использовать в любом месте (func do(v any) any, var v any, type foo interface { Do() any }) comparable - интерфейс, который определяет типы, которые могут быть сравнены с помощью == и != (переменные такого типа создать нельзя - var j comparable будет вызывать ошибку) И появилась возможность определять интерфейсы, которые можно будет использовать в параметризованных функциях и типах (переменные такого типа создать нельзя - var j Int будет вызывать ошибку):</p> <p><pre><code>type Int interface {
    int | int32 | int64
}
</code></pre> Если добавить знак ~ перед типами то интерфейсу будут соответствовать и производные типы, например myInt из примера ниже: <pre><code>type Int interface {
    ~int | ~int32 | ~int64
}

type myInt int
</code></pre> Разработчики golang создали для нас уже готовый набор интерфейсов (пакет constraints), который очень удобно использовать.</p> <p>Параметризованные функции Рассмотрим пример функции, что возвращает максимум из двух переданных значений, причём тип может быть любым: <pre><code>import "constraints"

func Max[T constraints.Ordered](a T, b T) T {
if a &gt; b {
    return a
}

return b
}
</code></pre> Ограничения на используемые типы описываются в квадратных скобочках. В качестве ограничения для типов можно использовать любой интерфейс и особые интерфейсы описанные выше.</p> <p>Для слайсов и мап был создан набор готовых полезных функций.</p> <p>Параметризованные типы <pre><code>import "reflect"

type myMap[K comparable, V any] map[K]V

func main() {
m := myMap[int, string]{5: "foo"}

    println(m[5])              // foo
    println(reflect.TypeOf(m)) // main.myMap[int,string]
}
</code></pre></p>

