    s1[1] = 222
}
func main() {
    s1 := make([]int, 1, 2)
    log.Printf("before: %v", s1) // [0]
    handle1(s1)
    log.Printf("after handlel: %v", s1) // [1 1 1]
    handle2(s1)
    log.Printf("after handle2: %v", s1) // [1 1 1]
    handle3(s1)
    log.Printf("after handle3: %v", s1) // panic: runtime error: index out of range [1] with length 1
}
</code></pre> Что будет выведено на экран? КодРешение <pre><code>package main
import (
    "fmt"
)

func add(arr []int, v int) {
    arr = append(arr, v) 
}

func main() {
    arr := make([]int, 0, 100000)
    fmt.Printf("%v %p\n", arr, &amp;arr) 
    add(arr, 10)
    fmt.Printf("%v %p\n", arr, &amp;arr) 
}
</code></pre> <pre><code>package main

import (
    "fmt"
